"""Regenerate the adversarial decks and MANIFEST.md.

    venv/bin/python -m tests.fixtures.adversarial.build            # every committed deck + MANIFEST.md
    venv/bin/python -m tests.fixtures.adversarial.build NEW-01 G001  # only names starting with these

Decks with `commit=False` (too big for git) are built by tests/test_adversarial.py into a temp folder.
"""
from __future__ import annotations

import sys
from pathlib import Path

from .decks import SPECS, Spec

HERE = Path(__file__).parent
DECKS = HERE / "decks"


def build(spec: Spec, folder: Path) -> Path:
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / spec.file
    if spec.saved:      # a real PowerPoint save: the builder only documents what it replaced
        assert path.exists(), f"{spec.file} is a saved PowerPoint file; it can't be regenerated"
        return path
    if path.exists():
        path.unlink()
    spec.build(path)
    return path


def manifest() -> str:
    def cell(s):
        return str(s).replace("|", "\\|").replace("\n", " ")

    rows = ["# Adversarial decks: manifest", "",
            "Generated by `venv/bin/python -m tests.fixtures.adversarial.build` from `decks.py`; edit that file, not "
            "this one. All content is made up.", "",
            "**Expected** is what SlideTistic should report on a scan (`problem` = red or yellow; `note` = low-priority "
            "yellow; `info` = inventory/fingerprint). **Fixed** = checks whose findings a repair should turn "
            "green_fixed. **Must not** = checks that must stay quiet (the look-alike half). **Known gap** = the test "
            "is xfail today, with the reason. **Layout** = the real answer needs PowerPoint (David's Mac).", "",
            "| Deck | Source | What's broken | Expected | Fixed | Must not | Layout | Known gap / note |",
            "| --- | --- | --- | --- | --- | --- | --- | --- |"]
    for s in SPECS:
        absent = ", ".join(str(a) if not isinstance(a, (tuple, list)) else " ".join(a) for a in s.absent)
        gap = s.xfail or ""
        if s.saved:
            gap += (" · " if gap else "") + "real PowerPoint save: " + s.saved
        elif s.real_ppt:
            gap += (" · " if gap else "") + "needs a real-PowerPoint copy: " + s.real_ppt
        if s.needs:
            gap += (" · " if gap else "") + "needs " + ", ".join(s.needs)
        if s.kind == "robust":
            gap += (" · " if gap else "") + f"expected outcome: {'plain error' if s.outcome == 'error' else 'scans and repairs'}"
        if not s.commit:
            gap += (" · " if gap else "") + "built by the test, not committed"
        rows.append(f"| `{s.file}` | {s.source} | {cell(s.broken)} | {cell(', '.join(map(str, s.expect)))} | "
                    f"{', '.join(s.fixed)} | {cell(absent)} | {'yes' if s.layout else ''} | {cell(gap)} |")
    return "\n".join(rows) + "\n"


def main(argv: list[str]) -> int:
    wanted = [s for s in SPECS if s.commit and (not argv or any(s.name.startswith(a) for a in argv))]
    for s in wanted:
        p = build(s, DECKS)
        print(f"{p.stat().st_size / 1024:8.0f} KB  {p.name}")
    if not argv:
        known = {s.file for s in SPECS if s.commit}
        for stale in DECKS.glob("*.pptx"):
            if stale.name not in known:
                stale.unlink()
                print(f"removed stale {stale.name}")
    (HERE / "MANIFEST.md").write_text(manifest(), encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
